import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.nkraVhM_.js";var i=JSON.parse(`{"title":"使い方ガイド","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/usage.md","filePath":"ja/guide/usage.md","lastUpdated":1793173149000}`),a={name:`ja/guide/usage.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="使い方ガイド" tabindex="-1">使い方ガイド <a class="header-anchor" href="#使い方ガイド" aria-label="Permalink to “使い方ガイド”">​</a></h1><h2 id="基本的なゲームプレイ" tabindex="-1">基本的なゲームプレイ <a class="header-anchor" href="#基本的なゲームプレイ" aria-label="Permalink to “基本的なゲームプレイ”">​</a></h2><h3 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to “目的”">​</a></h3><p>9×9 のグリッドを、すべての<strong>行</strong>、すべての<strong>列</strong>、そして 9 つの 3×3 <strong>ボックス</strong>のそれぞれに 1 から 9 までの数字がちょうど 1 回ずつ入るように埋めます。どのブロック内でも重複は許されません。</p><h3 id="遊び方" tabindex="-1">遊び方 <a class="header-anchor" href="#遊び方" aria-label="Permalink to “遊び方”">​</a></h3><ul><li><strong>数字を置く</strong>：空のマスをタップまたはクリックし、画面下部の数字パッドから数字をタップします。</li><li><strong>鉛筆メモ（候補）</strong>：鉛筆モードに切り替えてマスをタップすると、小さな候補数字を書き込めます。可能性を整理するのに便利です。</li><li><strong>消去</strong>：消去ボタンをタップすると、マスの値（鉛筆モードでは鉛筆メモ）が消えます。</li><li><strong>ヒント</strong>：ヒントをタップすると、正しいマスが 1 つ明かされます。</li><li><strong>元に戻す</strong>：元に戻すをタップすると直前の手が取り消されます（履歴はすべて保持されます）。</li></ul><h3 id="難易度" tabindex="-1">難易度 <a class="header-anchor" href="#難易度" aria-label="Permalink to “難易度”">​</a></h3><p>各難易度によって、開始時にあらかじめ埋まっている（初期配置の）マスの数が決まります：</p><table tabindex="0"><thead><tr><th>レベル</th><th>初期配置マス</th><th>こんな方に</th></tr></thead><tbody><tr><td>やさしい</td><td>45</td><td>初心者や短時間のプレイに</td></tr><tr><td>ふつう</td><td>36</td><td>気軽に楽しみたい方に</td></tr><tr><td>むずかしい</td><td>31</td><td>日常的に解く方に</td></tr><tr><td>エキスパート</td><td>27</td><td>経験を積んだ方に</td></tr><tr><td>マスター</td><td>24</td><td>パズルの達人に</td></tr></tbody></table><p><img src="/screenshot-mac-main.png" alt="Mac の Sudoku ゲームボード"></p><h2 id="操作方法" tabindex="-1">操作方法 <a class="header-anchor" href="#操作方法" aria-label="Permalink to “操作方法”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ul><li>空のマスを<strong>タップ</strong>して選択します</li><li>キーパッドの<strong>数字をタップ</strong>して配置します</li><li><strong>鉛筆モードを切り替えて</strong>、候補メモを入力・消去します</li><li><strong>消去</strong>でマスをクリアします</li><li>行き詰まったら<strong>ヒント</strong>を使います</li><li><strong>元に戻す</strong>で手を取り消します</li></ul><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h3><ul><li>空のマスを<strong>左クリック</strong>して選択します</li><li><strong>数字キー（1〜9）を入力</strong>するか、画面上のキーパッドをクリックして配置します</li><li><strong>鉛筆モードを切り替えて</strong>候補メモを入力します</li><li><strong>キーボードショートカット</strong>： <ul><li><code>⌘N</code> — 新しいゲーム</li><li><code>⌘Z</code> — 元に戻す</li><li><code>⌘1</code> 〜 <code>⌘5</code> — 各難易度で新しいゲームを開始</li></ul></li></ul><p><img src="/screenshot-iphone-main.png" alt="iPhone の Sudoku ホーム画面"></p><p><img src="/screenshot-ipad-main.png" alt="iPad の Sudoku ホーム画面"></p><h2 id="スマートな機能" tabindex="-1">スマートな機能 <a class="header-anchor" href="#スマートな機能" aria-label="Permalink to “スマートな機能”">​</a></h2><h3 id="鉛筆メモシステム" tabindex="-1">鉛筆メモシステム <a class="header-anchor" href="#鉛筆メモシステム" aria-label="Permalink to “鉛筆メモシステム”">​</a></h3><p>鉛筆モードを有効にすると、空のマスに小さな候補数字を書き込めます。スマートな鉛筆システムの特長：</p><ul><li><strong>同じ行・列・ボックスの鉛筆メモを自動消去</strong>：確定した数字を置くと、同じ行・列・ボックスにあるマスから、その数字の鉛筆メモが自動的に削除されます。</li><li><strong>マスごとに切り替え</strong>：入力モードと鉛筆モードはいつでも切り替えられます。</li></ul><h3 id="誤りチェック" tabindex="-1">誤りチェック <a class="header-anchor" href="#誤りチェック" aria-label="Permalink to “誤りチェック”">​</a></h3><p>任意で有効にできる誤り表示は、誤った入力を赤で示します。パズルの答えを明かさずに、間違いから学べます。</p><h3 id="デイリーチャレンジ" tabindex="-1">デイリーチャレンジ <a class="header-anchor" href="#デイリーチャレンジ" aria-label="Permalink to “デイリーチャレンジ”">​</a></h3><p>毎日、マスターレベルの新しいパズルが生成されます。デイリーチャレンジの進捗は統計で記録され、連続記録をカレンダー表示で確認できます。</p><h3 id="統計" tabindex="-1">統計 <a class="header-anchor" href="#統計" aria-label="Permalink to “統計”">​</a></h3><p>数独の歩みを記録できます：</p><ul><li>総プレイ数と勝率</li><li>現在の連続記録と最高連続記録</li><li>難易度ごとの内訳：クリア数、ベストタイム、平均タイム</li><li>クリア状況が分かるデイリーチャレンジのカレンダー</li></ul><p><img src="/screenshot-mac-settings.png" alt="Mac の Sudoku 統計画面"></p><h2 id="テーマ" tabindex="-1">テーマ <a class="header-anchor" href="#テーマ" aria-label="Permalink to “テーマ”">​</a></h2><p>設定から 8 種類の美しいカラーテーマを選べます：</p><table tabindex="0"><thead><tr><th>テーマ</th><th>スタイル</th></tr></thead><tbody><tr><td>クラシック</td><td>青をアクセントにした清潔感のある白</td></tr><tr><td>ミッドナイト</td><td>深い青のダークモード</td></tr><tr><td>ペーパー</td><td>温かみのある羊皮紙の質感</td></tr><tr><td>フォレスト</td><td>自然なグリーン</td></tr><tr><td>オーシャン</td><td>穏やかな海のブルー</td></tr><tr><td>サンセット</td><td>温かなオレンジのグラデーション</td></tr><tr><td>ラベンダー</td><td>柔らかな紫の色調</td></tr><tr><td>ローズ</td><td>上品なピンクのパレット</td></tr></tbody></table><h2 id="icloud-同期" tabindex="-1">iCloud 同期 <a class="header-anchor" href="#icloud-同期" aria-label="Permalink to “iCloud 同期”">​</a></h2><p>デバイスで iCloud にサインインしている場合：</p><ul><li>ゲームのセーブデータが自動的に同期され、どのデバイスでも続きから遊べます</li><li>統計と設定も同期されたまま保たれます</li><li>デイリーチャレンジの進捗がデバイス間で引き継がれます</li><li>iOS/iPadOS 16 以降または macOS 15 以降が必要です</li></ul><h2 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h2><p>Game Center に接続すると、次のことができます：</p><ul><li>難易度ごとのベストクリアタイムで<strong>リーダーボード</strong>を競う</li><li><strong>実績</strong>を獲得する：First Solve、Easy／Medium／Hard／Expert／Master Clear、Flawless（ヒントも誤りもなし）</li></ul><h2 id="パズルの印刷-mac" tabindex="-1">パズルの印刷（Mac） <a class="header-anchor" href="#パズルの印刷-mac" aria-label="Permalink to “パズルの印刷（Mac）”">​</a></h2><p>Mac では、アプリから直接パズルを印刷できます：</p><ol><li>ツールバーから<strong>印刷</strong>ダイアログを開きます</li><li>難易度（やさしい〜マスター）を選択します</li><li>必要に応じて「解答を含める」をオンにします</li><li><strong>印刷</strong>をクリックします</li></ol><p>ペンと紙でオフラインに解くのに最適です！</p><h2 id="効果音" tabindex="-1">効果音 <a class="header-anchor" href="#効果音" aria-label="Permalink to “効果音”">​</a></h2><p>Sudoku には控えめな効果音が用意されています：</p><ul><li>数字配置の確認音</li><li>ヒントの表示</li><li>誤りの警告</li><li>勝利の演出</li></ul><p><strong>設定 → サウンド</strong> で音のオン／オフを切り替えられます。</p><h2 id="ヒントとコツ" tabindex="-1">ヒントとコツ <a class="header-anchor" href="#ヒントとコツ" aria-label="Permalink to “ヒントとコツ”">​</a></h2><ul><li><strong>埋まっているマスから始める</strong> — すでに多くの数字が入っている行・列・ボックスを先に調べましょう。</li><li><strong>鉛筆メモを活用する</strong> — むずかしい、エキスパート、マスターの難易度では特に役立ちます。</li><li><strong>ネイキッドシングルを探す</strong> — あるマスの候補が 1 つだけなら、それを書き入れましょう。</li><li><strong>ヒドゥンシングルを探す</strong> — ある数字が行・列・ボックス内の 1 か所にしか置けないなら、そこに配置します。</li><li><strong>ヒントは控えめに</strong> — 学習には最適ですが、ヒントなしで解き切ったほうが達成感は大きいものです。</li><li><strong>毎日の連続記録を伸ばす</strong> — デイリーチャレンジは習慣的に練習するのに最適な方法です。</li></ul>`,48)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};